      SUBROUTINE FITDEFC---- STORE REFERENCE TO MATRIX ELEMENTC---------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATUM.CIN'      INCLUDE 'ICODE.CIN'      INCLUDE 'RDPRNT.CIN'      INCLUDE 'RDWRDS.CIN'      INCLUDE 'STACK.CIN'      INCLUDE 'VARY.CIN'C      EQUIVALENCE     (FAKE,LAKE)C---------------------------------------------------------------------CC     STORE MATRIX ELEMENT SPECIFICATIONC      IF (INDS .EQ. 0) THEN        NWORD = 4        NDESC = 7        LAKE = 22        DATUM(1) = FAKE        LAKE = ICODE        DATUM(2) = FAKE        LAKE = JCODE        DATUM(3) = FAKE        LAKE = LEV        DATUM(4) = FAKE        IF (ICODE .EQ. 9) VARY(3) = 100        CALL ELSTOR        IVAL(LEV) = LEV        IREF(LEV) = 0        IF (ICODE .EQ. 9) IREF(LEV) = 100      ENDIF      RETURN      END